/// @dev Verify settlement conservation with non-zero exchange fees
function test_C17_settlement_conservation_with_fees() public {
    // Enable protocol exchange fees
    changePrank(AMM_ADMIN);
    amm.setProtocolFees(ProtocolFeeStructure({lpFeeBPS: 1000, exchangeFeeBPS: 500, feeOnTopBPS: 500}));
    changePrank(address(this));

    (bytes32 _poolId, address token0, address token1) = _setupPool();
    address feeRecipient = makeAddr("feeRecipient");

    // Snapshot balances before
    uint256[4] memory before;
    before[0] = IERC20(token0).balanceOf(alice);
    before[1] = IERC20(token0).balanceOf(feeRecipient);
    before[2] = IERC20(token0).balanceOf(address(amm));
    before[3] = IERC20(token1).balanceOf(address(amm));

    changePrank(alice);
    amm.singleSwap(
        SwapOrder({
            deadline: block.timestamp + 1000,
            recipient: alice,
            amountSpecified: int256(10e18),
            limitAmount: 0,
            minAmountSpecified: 0,
            tokenIn: token0,
            tokenOut: token1
        }),
        _poolId,
        BPSFeeWithRecipient({BPS: 100, recipient: feeRecipient}),
        FlatFeeWithRecipient({amount: 1e17, recipient: feeRecipient}),
        _emptySwapHooksExtraData(),
        bytes("")
    );

    // Snapshot balances after
    uint256[4] memory aft;
    aft[0] = IERC20(token0).balanceOf(alice);
    aft[1] = IERC20(token0).balanceOf(feeRecipient);
    aft[2] = IERC20(token0).balanceOf(address(amm));
    aft[3] = IERC20(token1).balanceOf(address(amm));

    // Conservation: alice's loss = AMM gain + fee recipient gain
    uint256 aliceLoss0 = before[0] - aft[0];
    uint256 recipientGain0 = aft[1] - before[1];
    uint256 ammGain0 = aft[2] - before[2];
    assertEq(aliceLoss0, ammGain0 + recipientGain0, "C17: Token0 conservation in settlement");

